<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { useAuthStore } from '../stores/auth'
const auth = useAuthStore(); const form = reactive({ name: auth.currentUser?.name ?? '', email: auth.currentUser?.email ?? '', updates: true }); const success = ref(''); const errors = reactive<Record<string,string>>({}); const isValid = computed(() => form.name.trim().length > 1 && form.email.includes('@'))
function validate() { errors.name = form.name.trim().length > 1 ? '' : 'Name is required'; errors.email = form.email.includes('@') ? '' : 'Enter a valid email'; return !errors.name && !errors.email }
function onSubmit() { if (!validate()) return; success.value = 'Changes saved successfully.' }
</script><template><div class="max-w-3xl"><h1 class="text-3xl font-bold">Settings</h1><p class="mt-2 text-sm text-secondary">Manage your personal workspace preferences.</p><form class="mt-7 rounded-panel border border-border bg-surface p-6 sm:p-8" @submit.prevent="onSubmit"><h2 class="text-lg font-bold">Profile</h2><div class="mt-5 grid gap-5 sm:grid-cols-2"><label class="text-sm font-medium">Name<input v-model="form.name" @blur="validate" class="mt-2 w-full rounded-lg border border-border px-3 py-2.5" /><span v-if="errors.name" class="text-xs text-danger">{{ errors.name }}</span></label><label class="text-sm font-medium">Email<input v-model="form.email" @blur="validate" type="email" class="mt-2 w-full rounded-lg border border-border px-3 py-2.5" /><span v-if="errors.email" class="text-xs text-danger">{{ errors.email }}</span></label></div><div class="mt-8 border-t border-border pt-6"><h2 class="text-lg font-bold">Notifications</h2><label class="mt-4 flex cursor-pointer items-center justify-between rounded-lg bg-surface-muted p-4 text-sm"><span><span class="block font-semibold">Product updates</span><span class="text-secondary">Receive important workspace updates by email.</span></span><input v-model="form.updates" type="checkbox" class="h-4 w-4 accent-primary" /></label></div><p v-if="success" class="mt-5 rounded-lg bg-success/10 p-3 text-sm text-success">{{ success }}</p><button :disabled="!isValid" class="mt-7 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50">Save changes</button></form></div></template>
